@ Effect node function pointer table handler. Extracts player_id (bit0) and card_type (bits[4:1]) from slot_node [r0+2]. Calls find_slot_idx_by_card_id_in_player_zones to find card slot index in player zones; if not found (r5<0) returns 0. Calls count_available_monster_slots; if 0 returns 0. Calls check_field_spell_neo_daedalus_group_placeable; if fails returns 0. On all checks passing, computes EWRAM equip zone offset (0x0201c600 + player*0x868 + slot*4), calls invoke_setup_equip_oam_with_attr2 to enqueue OAM attr. Called via function pointer table (Sub-type B).
@ 
@ Constants:
@ - EQUIP_ZONE_BASE=0x0201c600 (equip zone EWRAM base, DWORD_08079ec0)
@ - PLAYER_STRIDE=0x868 (per-player offset stride, DWORD_08079ebc)
@ - ATTR2_MODE=1 (invoke_setup_equip_oam_with_attr2 r2 param)
enqueue_neo_daedalus_zone_oam_on_available_slot:
    push {r4,r5,lr}                          @ 08079e60 30b5
    adds r4,r0,#0x0    @ 08079e62 041c
    ldrb r1,[r4,#0x2]                        @ 08079e64 a178
    lsls r0,r1,#0x1f    @ 08079e66 c807
    lsrs r0,r0,#0x1f    @ 08079e68 c00f
    ldrh r2,[r4,#0x4]                        @ 08079e6a a288
    lsls r1,r2,#0x11    @ 08079e6c 5104
    lsrs r1,r1,#0x17    @ 08079e6e c90d
    bl find_slot_idx_by_card_id_in_player_zones @ 08079e70 b7f73cfa
    adds r5,r0,#0x0    @ 08079e74 051c
    cmp r5,#0x0                              @ 08079e76 002d
    blt LAB_08079eb4                         @ 08079e78 1cdb
    ldrb r1,[r4,#0x2]                        @ 08079e7a a178
    lsls r0,r1,#0x1f    @ 08079e7c c807
    lsrs r0,r0,#0x1f    @ 08079e7e c00f
    bl count_available_monster_slots         @ 08079e80 b9f79afb
    cmp r0,#0x0                              @ 08079e84 0028
    beq LAB_08079eb4                         @ 08079e86 15d0
    ldrb r2,[r4,#0x2]                        @ 08079e88 a278
    lsls r0,r2,#0x1f    @ 08079e8a d007
    lsrs r0,r0,#0x1f    @ 08079e8c c00f
    bl check_field_spell_neo_daedalus_group_placeable @ 08079e8e c1f775fe
    cmp r0,#0x0                              @ 08079e92 0028
    beq LAB_08079eb4                         @ 08079e94 0ed0
    ldrb r0,[r4,#0x2]                        @ 08079e96 a078
    lsls r1,r0,#0x1f    @ 08079e98 c107
    lsrs r0,r1,#0x1f    @ 08079e9a c80f
    adds r1,r0,#0x0    @ 08079e9c 011c
    ldr r2, DWORD_08079ebc                   @ 08079e9e 074a
    muls r1,r2    @ 08079ea0 5143
    ldr r2, DWORD_08079ec0                   @ 08079ea2 074a
    adds r1,r1,r2    @ 08079ea4 8918
    lsls r2,r5,#0x2    @ 08079ea6 aa00
    adds r1,r1,r2    @ 08079ea8 8918
    ldrh r4,[r4,#0x0]                        @ 08079eaa 2488
    lsls r3,r4,#0x10    @ 08079eac 2304
