    push {r4,r5,lr}                          @ 0807a0f4 30b5
    adds r5,r0,#0x0    @ 0807a0f6 051c
    ldrb r1,[r5,#0x2]                        @ 0807a0f8 a978
    lsls r0,r1,#0x1f    @ 0807a0fa c807
    lsrs r0,r0,#0x1f    @ 0807a0fc c00f
