    movs r3,#0x0    @ 0807a102 0023
    bl enqueue_sprite_attr_type11            @ 0807a104 d0f7bef9
    movs r0,#0x4    @ 0807a108 0420
    ldrb r1,[r5,#0x4]                        @ 0807a10a 2979
    ands r0,r1    @ 0807a10c 0840
    cmp r0,#0x0                              @ 0807a10e 0028
    bne LAB_0807a12c                         @ 0807a110 0cd1
    ldrb r1,[r5,#0x2]                        @ 0807a112 a978
    lsls r0,r1,#0x1f    @ 0807a114 c807
    lsrs r0,r0,#0x1f    @ 0807a116 c00f
