    lsrs r6,r1,#0x18    @ 0807a2da 0e0e
    lsls r0,r0,#0x10    @ 0807a2dc 0004
    lsrs r5,r0,#0x18    @ 0807a2de 050e
    adds r0,r4,#0x0    @ 0807a2e0 201c
    adds r1,r6,#0x0    @ 0807a2e2 311c
    adds r2,r5,#0x0    @ 0807a2e4 2a1c
    bl invoke_effect_node_with_active_flag_3arg @ 0807a2e6 16f09df9
    cmp r0,#0x0                              @ 0807a2ea 0028
    beq LAB_0807a2fe                         @ 0807a2ec 07d0
    ldrh r2,[r4,#0x0]                        @ 0807a2ee 2288
